/*
 * V8 ApiEngine
 * ApiEngineKey: msg_internal_mark_read
 * Version: v1.0.0
 * Function:
 * - 将当前登录用户的一条或全部平台内部通知标为已读，先按当前用户Id和固定通知方式鉴权，拒绝按Id越权。
 */

// @version 1.0.0
// 仅允许当前用户修改自己的平台内部通知，避免按Id越权。
if (!V8.CurrentUser || !V8.CurrentUser.Id) return { Code: 1001, Msg: '请先登录！' };

var currentUserId = String(V8.CurrentUser.Id);
var readTime = DateNow('yyyy-MM-dd HH:mm:ss');
var markAll = V8.Param.All === true || Number(V8.Param.All || 0) === 1 || String(V8.Param.All || '').toLowerCase() === 'true';

if (markAll) {
  var allResult = V8.FormEngine.UptFormDataByWhere('mic_msg_event_log', {
    _Where: [
      ['ReceiverUserId', '=', currentUserId],
      ['ChannelType', '=', '平台内部'],
      ['IsRead', '<>', 1]
    ],
    IsRead: 1,
    ReadTime: readTime
  });
  if (!allResult || allResult.Code !== 1) return allResult;
  return { Code: 1, Data: { All: true, ReadTime: readTime }, Msg: '平台内部通知已全部标为已读。' };
}

var id = String(V8.Param.Id || '').trim();
if (!id) return { Code: 0, Msg: 'Id不能为空！' };
var ownResult = V8.FormEngine.GetFormData('mic_msg_event_log', {
  _Where: [
    ['Id', '=', id],
    ['ReceiverUserId', '=', currentUserId],
    ['ChannelType', '=', '平台内部']
  ],
  _SelectFields: ['Id', 'IsRead']
});
if (!ownResult || ownResult.Code !== 1) return { Code: 0, Msg: '通知不存在或无权操作！' };
if (Number(ownResult.Data.IsRead || 0) === 1) {
  return { Code: 1, Data: { Id: id, ReadTime: readTime, Skipped: true }, Msg: '通知已是已读状态。' };
}

var updateResult = V8.FormEngine.UptFormData('mic_msg_event_log', {
  Id: id,
  IsRead: 1,
  ReadTime: readTime
});
if (!updateResult || updateResult.Code !== 1) return updateResult;
return { Code: 1, Data: { Id: id, ReadTime: readTime }, Msg: '通知已标为已读。' };

/* OFFICIAL_MANAGED_API_ENGINE_NOTICE_V1
 * 【极重要：这是官方应用托管接口，禁止直接承载个性化代码】
