/*
 * V8 ApiEngine
 * ApiEngineKey: msg_internal_list
 * Version: v1.0.3
 * Function:
 * - 查询当前用户的平台内部通知列表：以唯一 AI助手 身份返回，并与普通 AI 聊天历史合并显示、共同管理未读状态。
 */

// @version 1.0.1
// 当前用户的平台内部通知权威快照；SignalR 事件只用于提示本接口重新回读。
if (!V8.CurrentUser || !V8.CurrentUser.Id) return { Code: 1001, Msg: '请先登录！' };

var pageIndex = Number(V8.Param._PageIndex || 1);
var pageSize = Number(V8.Param._PageSize || 50);
if (!isFinite(pageIndex) || pageIndex < 1) pageIndex = 1;
if (!isFinite(pageSize) || pageSize < 1) pageSize = 50;
pageSize = Math.min(100, Math.floor(pageSize));

var where = [
  ['ReceiverUserId', '=', String(V8.CurrentUser.Id)],
  ['ChannelType', '=', '平台内部']
];
if (V8.Param.IsRead !== undefined && V8.Param.IsRead !== null && V8.Param.IsRead !== '') {
  where.push(['IsRead', '=', Number(V8.Param.IsRead) === 1 ? 1 : 0]);
}

var listResult = V8.FormEngine.GetTableData('mic_msg_event_log', {
  _Where: where,
  _SelectFields: ['Id', 'EventId', 'MsgEventId', 'ChannelType', 'Title', 'MsgContent', 'LinkUrl', 'Payload', 'IsSuccess', 'IsRead', 'ReadTime', 'CreateTime'],
  _OrderBy: 'CreateTime',
  _OrderByType: 'DESC',
  _PageIndex: pageIndex,
  _PageSize: pageSize
});
if (!listResult || listResult.Code !== 1) return listResult;

var unreadResult = V8.FormEngine.GetTableDataCount('mic_msg_event_log', {
  _Where: [
    ['ReceiverUserId', '=', String(V8.CurrentUser.Id)],
    ['ChannelType', '=', '平台内部'],
    ['IsRead', '<>', 1]
  ]
});
var unreadCount = unreadResult && unreadResult.Code === 1 ? Number(unreadResult.Data || 0) : 0;
var items = listResult.Data || [];
for (var itemIndex = 0; itemIndex < items.length; itemIndex++) {
  items[itemIndex].MessageKind = 'PlatformSystem';
  items[itemIndex].SenderUserId = 'AI';
  items[itemIndex].SenderAccount = 'AI';
  items[itemIndex].SenderName = 'AI助手';
  items[itemIndex].ReadOnly = false;
}
return {
  Code: 1,
  Data: items,
  DataCount: Number(listResult.DataCount || 0),
  DataAppend: { UnreadCount: unreadCount },
  Msg: ''
};

/* OFFICIAL_MANAGED_API_ENGINE_NOTICE_V1
 * 【极重要：这是官方应用托管接口，禁止直接承载个性化代码】
 * 所属官方应用：消息通知
 * ApiEngineKey：msg_event
 * 从可信吾码官方应用源安装、更新或重新安装“消息通知”，都会以官方源码恢复此 Managed 接口。
 * 强烈建议仅修改该应用声明的 CreateIfMissing 个性化 Hook；若当前阶段没有 Hook，
 * 请新增独立租户接口并由官方接口通过受支持扩展点调用，禁止直接修改本接口。
 */

/*
 * V8 ApiEngine
 * ApiEngineKey: msg_event
 * Version: v1.0.3
 * Function:
 * - 统一消息通知入口：按配置解析接收人和通道；平台内部通知持久化后，以唯一 AI助手 身份投影到聊天会话并通过 SignalR 实时提示。
 */

// @version 2.0.1
// 统一消息通知编排：持久化日志是事实源，SignalR 只作为提交后的实时提示。

function toArray(value) {
  if (value === null || value === undefined || value === '') return [];
  if (typeof value === 'string') {
    var text = value.trim();
    if (!text) return [];
    if (text.charAt(0) === '[' || text.charAt(0) === '{') {
      try { return toArray(JSON.parse(text)); } catch (ignore) {}
    }
    return text.split(',');
  }
  if (typeof value.length === 'number') {
    var list = [];
    for (var i = 0; i < value.length; i++) list.push(value[i]);
    return list;
  }
  return [value];
}

function parseJson(value, fallback) {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'object') return value;
  try { return JSON.parse(String(value)); } catch (ignore) { return fallback; }
}

function buildPlatformPayload(value) {
  var result = {};
  if (value && typeof value === 'object' && typeof value.length !== 'number') {
    for (var key in value) {
      if (Object.prototype.hasOwnProperty.call(value, key)) result[key] = value[key];
    }
  } else if (value !== null && value !== undefined && value !== '') {
    result.Data = value;
  }
  // 平台内部通知统一投影到可交互的 AI助手 会话，不再创建独立系统联系人。
  // 这些身份字段由受信任的消息核心覆盖，调用方不能伪造其它发送人。
  result.MessageKind = 'PlatformSystem';
  result.SenderUserId = 'AI';
  result.SenderAccount = 'AI';
  result.SenderName = 'AI助手';
  result.ReadOnly = false;
  return result;
}

function readId(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string' || typeof value === 'number') return String(value).trim();
  return String(value.Id || value.UserId || value.ReceiverUserId || '').trim();
}

function isEnabled(value) {
  if (value === null || value === undefined || value === '') return true;
  var normalized = String(value).toLowerCase();
  return normalized === '1' || normalized === 'true';
}

function normalizeLink(value) {
  var link = String(value || '').trim();
  if (!link) return '';
  if (link.length > 500) return null;
  if (link.charAt(0) === '#' || (/^\/(?!\/)/).test(link) || (/^https?:\/\//i).test(link)) return link;
  return null;
}

function compactResult(result, state) {
  return JSON.stringify({
    State: state,
    Code: result && result.Code !== undefined ? result.Code : 0,
    Msg: String(result && result.Msg ? result.Msg : '').substring(0, 1000)
  });
}

function addFailure(message) {
  if (failureMessages.length < 20) failureMessages.push(String(message || '').substring(0, 500));
}

function findLog(eventId, channelType, receiverUserId) {
  return V8.FormEngine.GetFormData('mic_msg_event_log', {
    _Where: [
      ['EventId', '=', eventId],
      ['ChannelType', '=', channelType],
      ['ReceiverUserId', '=', receiverUserId]
    ],
    _SelectFields: ['Id', 'EventId', 'ChannelType', 'ReceiverUserId', 'IsSuccess', 'MsgResult']
  });
}

function claimLog(user, channelType, messageTitle, messageContent, linkUrl, payload) {
  var existing = findLog(eventId, channelType, user.Id);
  if (existing && existing.Code === 1) {
    return { Duplicate: true, Id: existing.Data.Id };
  }

  var logId = V8.Method.NewUlid();
  var addResult = V8.FormEngine.AddFormData('mic_msg_event_log', {
    Id: logId,
    MsgEventId: msgSetModel.Id,
    EventId: eventId,
    ChannelType: channelType,
    ReceiverUserId: user.Id,
    Receivers: JSON.stringify([{ Id: user.Id, Name: user.Name || user.Account || '' }]),
    Title: messageTitle,
    MsgContent: messageContent,
    LinkUrl: linkUrl,
    Payload: JSON.stringify(payload || {}),
    MsgResult: JSON.stringify({ State: 'Dispatching' }),
    IsSuccess: 0,
    IsRead: channelType === '平台内部' ? 0 : 1,
    ReadTime: channelType === '平台内部' ? '' : DateNow('yyyy-MM-dd HH:mm:ss')
  });
  if (addResult && addResult.Code === 1) return { Duplicate: false, Id: logId };

  // 多节点同时处理同一 EventId 时，唯一索引只允许一个节点取得发送资格。
  existing = findLog(eventId, channelType, user.Id);
  if (existing && existing.Code === 1) return { Duplicate: true, Id: existing.Data.Id };
  return { Error: true, Result: addResult };
}

function finishLog(logId, result, success) {
  return V8.FormEngine.UptFormData('mic_msg_event_log', {
    Id: logId,
    MsgResult: compactResult(result, success ? 'Succeeded' : 'Failed'),
    IsSuccess: success ? 1 : 0
  });
}

if (!V8.Param.MsgKey) return { Code: 0, Msg: 'MsgKey不能为空！' };

var msgSetResult = V8.FormEngine.GetFormData('mic_msgset', {
  _Where: [['Key', '=', V8.Param.MsgKey]]
});
if (!msgSetResult || msgSetResult.Code !== 1) return msgSetResult;

var msgSetModel = msgSetResult.Data;
if (!isEnabled(msgSetModel.IsEnable)) return { Code: 0, Msg: '消息通知配置未启用！' };

var channels = toArray(msgSetModel.Type);
var normalizedChannels = [];
for (var channelIndex = 0; channelIndex < channels.length; channelIndex++) {
  var channelName = String(channels[channelIndex] || '').trim();
  if (channelName && normalizedChannels.indexOf(channelName) < 0) normalizedChannels.push(channelName);
}
if (normalizedChannels.length === 0) return { Code: 0, Msg: '未配置通知方式！' };

var eventId = String(V8.Param.EventId || V8.Param.IdempotencyKey || V8.Method.NewUlid()).trim();
if (!(/^[A-Za-z0-9][A-Za-z0-9._:-]{0,99}$/).test(eventId)) {
  return { Code: 0, Msg: 'EventId格式无效！' };
}

var linkUrl = normalizeLink(V8.Param.LinkUrl || V8.Param.Url || '');
if (linkUrl === null) return { Code: 0, Msg: 'LinkUrl仅支持站内路径、锚点或http/https地址，且不能超过500个字符！' };

var userById = {};
var userModels = [];
function addUser(user) {
  if (!user || !user.Id) return;
  var key = String(user.Id).toLowerCase();
  if (userById[key]) return;
  var safeUser = {
    Id: String(user.Id),
    Account: String(user.Account || ''),
    Name: String(user.Name || ''),
    WxOpenId: String(user.WxOpenId || ''),
    Email: String(user.Email || ''),
    Phone: String(user.Phone || '')
  };
  userById[key] = safeUser;
  userModels.push(safeUser);
}

var directIds = [];
var receiverSources = [
  msgSetModel.Receivers,
  V8.Param.ReceiverUserIds,
  V8.Param.ReceiverUserId,
  V8.Param.Receivers
];
for (var sourceIndex = 0; sourceIndex < receiverSources.length; sourceIndex++) {
  var sourceItems = toArray(receiverSources[sourceIndex]);
  for (var sourceItemIndex = 0; sourceItemIndex < sourceItems.length; sourceItemIndex++) {
    var directId = readId(sourceItems[sourceItemIndex]);
    if (directId && directIds.indexOf(directId) < 0) directIds.push(directId);
  }
}
if (directIds.length > 0) {
  var directUsersResult = V8.FormEngine.GetTableData('sys_user', {
    _Where: [['Id', 'In', directIds]],
    _SelectFields: ['Id', 'Account', 'Name', 'WxOpenId', 'Email', 'Phone'],
    _PageIndex: 1,
    _PageSize: Math.min(201, directIds.length)
  });
  if (directUsersResult && directUsersResult.Code === 1) {
    var directUsers = toArray(directUsersResult.Data);
    for (var directUserIndex = 0; directUserIndex < directUsers.length; directUserIndex++) addUser(directUsers[directUserIndex]);
  }
}

var roleItems = toArray(msgSetModel.ReceiversRoles);
if (roleItems.length > 50) return { Code: 0, Msg: '接收角色不能超过50个！' };
for (var roleIndex = 0; roleIndex < roleItems.length; roleIndex++) {
  var roleId = readId(roleItems[roleIndex]);
  if (!roleId) continue;
  var roleUsersResult = V8.FormEngine.GetTableData('sys_user', {
    _Where: [['RoleIds', 'Like', roleId]],
    _SelectFields: ['Id', 'Account', 'Name', 'WxOpenId', 'Email', 'Phone'],
    _PageIndex: 1,
    _PageSize: 201
  });
  if (roleUsersResult && roleUsersResult.Code === 1) {
    var roleUsers = toArray(roleUsersResult.Data);
    for (var roleUserIndex = 0; roleUserIndex < roleUsers.length; roleUserIndex++) addUser(roleUsers[roleUserIndex]);
  }
  if (userModels.length > 200) return { Code: 0, Msg: '单次消息通知最多发送给200个用户！' };
}
if (userModels.length === 0) return { Code: 0, Msg: '未找到任何有效接收用户！' };
if (userModels.length > 200) return { Code: 0, Msg: '单次消息通知最多发送给200个用户！' };

var payload = parseJson(V8.Param.Payload, V8.Param.Payload || {});
var defaultTitle = String(V8.Param.Title || msgSetModel.Title || V8.Param.MsgKey).trim();
var defaultContent = String(V8.Param.Content || V8.Param.MsgContent || msgSetModel.Title || '').trim();
var adapterMap = parseJson(msgSetModel.ChannelApiEngineMap, {});
var notificationHostAvailable = typeof V8.Notification !== 'undefined'
  && V8.Notification
  && typeof V8.Notification.Send === 'function';

var succeeded = 0;
var failed = 0;
var claimed = 0;
var duplicate = 0;
var logIds = [];
var failureMessages = [];
var wechatReady = false;
var tplModel = null;
var tplData = null;
var pagePath = '';
if (normalizedChannels.indexOf('微信公众号模板消息') >= 0) {
  if (!msgSetModel.WxTplMsgId) {
    addFailure('微信公众号模板消息未设置消息模板。');
  } else {
    var tplResult = V8.FormEngine.GetFormData('wx_tpl_msg', { Id: msgSetModel.WxTplMsgId });
    if (tplResult && tplResult.Code === 1) {
      tplModel = tplResult.Data;
      tplData = parseJson(tplModel.Content, {});
      if (V8.Param.TemplateData && typeof V8.Param.TemplateData === 'object') {
        for (var templateKey in V8.Param.TemplateData) {
          if (!Object.prototype.hasOwnProperty.call(V8.Param.TemplateData, templateKey)) continue;
          var templateValue = V8.Param.TemplateData[templateKey];
          tplData[templateKey] = templateValue && typeof templateValue === 'object' && templateValue.value !== undefined
            ? templateValue
            : { value: templateValue };
        }
      }
      pagePath = String(tplModel.MiniProgramPagePath || '');
      if (V8.Param.PagePathParam) {
